use chrono::{DateTime, Datelike, Local, Timelike};
use serde::{Deserialize, Serialize};
use tauri::Manager;
use windows::{core::PCWSTR, Win32::{Foundation::{GetLastError, RECT}, Graphics::{Gdi::{CreateDCW, CreateFontW, DeleteDC, DeleteObject, DrawTextW, EndDoc, EndPage, GetDeviceCaps, MulDiv, SelectObject, StartDocW, StartPage, DOCINFOW, HORZRES, LOGPIXELSY, FW_BOLD, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, DEFAULT_QUALITY, DEFAULT_PITCH, DT_RIGHT, DT_RTLREADING, DT_SINGLELINE}, Printing::{EnumPrintersW, PRINTER_ENUM_LOCAL, PRINTER_ENUM_CONNECTIONS, PRINTER_INFO_2W}}}};
#[derive(Serialize)] struct Printer{name:String,status:String,driver:String}
#[derive(Deserialize)] struct Sale{id:i64,product_name:String,quantity:f64,unit_price:f64,total:f64,created_at:String}
fn wide(s:&str)->Vec<u16>{s.encode_utf16().chain(std::iter::once(0)).collect()}
fn last_error(s:&str)->String{format!("{s}: Windows error {:?}",unsafe{GetLastError()})}
#[tauri::command] fn list_printers()->Result<Vec<Printer>,String>{unsafe{let flags=PRINTER_ENUM_LOCAL|PRINTER_ENUM_CONNECTIONS;let(mut needed,mut count)=(0u32,0u32);let _=EnumPrintersW(flags,PCWSTR::null(),2,None,0,&mut needed,&mut count);if needed==0{return Ok(vec![])}let mut b=vec![0u8;needed as usize];if !EnumPrintersW(flags,PCWSTR::null(),2,Some(b.as_mut_ptr()),needed,&mut needed,&mut count).as_bool(){return Err(last_error("تعذر البحث عن طابعات Windows"))}let rows=std::slice::from_raw_parts(b.as_ptr() as *const PRINTER_INFO_2W,count as usize);Ok(rows.iter().map(|p|Printer{name:p.pPrinterName.to_string().unwrap_or_default(),status:"Windows queue موجودة".into(),driver:p.pDriverName.to_string().unwrap_or_default()}).collect())}}
fn print_gdi(queue:&str,s:&Sale,width:u16)->Result<String,String>{unsafe{let q=wide(queue);let driver=wide("WINSPOOL");let dc=CreateDCW(PCWSTR(driver.as_ptr()),PCWSTR(q.as_ptr()),PCWSTR::null(),None);if dc.is_invalid(){return Err(last_error("تعذر فتح Windows Print Queue"))}let title=wide(&format!("عملية {} - مخبز أولاد عثمان",s.id));let doc=DOCINFOW{cbSize:std::mem::size_of::<DOCINFOW>() as i32,lpszDocName:PCWSTR(title.as_ptr()),lpszOutput:PCWSTR::null(),lpszDatatype:PCWSTR::null(),fwType:0};if StartDocW(dc,&doc)<=0{let e=last_error("تعذر بدء مهمة الطباعة");let _=DeleteDC(dc);return Err(e)}let dpi=GetDeviceCaps(dc,LOGPIXELSY).max(96);let _paper=width;let face=wide("Arial");let font=CreateFontW(-MulDiv(11,dpi,72),0,0,0,FW_BOLD.0 as i32,0,0,0,DEFAULT_CHARSET.0 as u32,OUT_DEFAULT_PRECIS.0 as u32,CLIP_DEFAULT_PRECIS.0 as u32,DEFAULT_QUALITY.0 as u32,DEFAULT_PITCH.0 as u32,PCWSTR(face.as_ptr()));let old=SelectObject(dc,font);if StartPage(dc)<=0{let e=last_error("تعذر بدء صفحة الطباعة");let _=EndDoc(dc);let _=DeleteObject(old);let _=DeleteObject(font);let _=DeleteDC(dc);return Err(e)}let stamp=DateTime::parse_from_rfc3339(&s.created_at).map(|d|d.with_timezone(&Local)).unwrap_or_else(|_|Local::now());let day=["الأحد","الإثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"][stamp.weekday().num_days_from_sunday() as usize];let month=["يناير","فبراير","مارس","أبريل","مايو","يونيو","يوليو","أغسطس","سبتمبر","أكتوبر","نوفمبر","ديسمبر"][stamp.month0() as usize];let margin=MulDiv(3,dpi,25);let mut y=margin;let line=MulDiv(16,dpi,72);let right=GetDeviceCaps(dc,HORZRES).max(1)-margin;let rows=["مخبز أولاد عثمان".to_string(),"--------------------------------".into(),format!("التاريخ: {} {} {}",stamp.day(),month,stamp.year()),format!("اليوم: {}",day),format!("الوقت: {:02}:{:02}",stamp.hour(),stamp.minute()),"--------------------------------".into(),format!("رقم العملية: {}",s.id),format!("نوع العيش: {}",s.product_name),format!("الكمية: {}",s.quantity),format!("سعر الوحدة: {:.2} ج.م",s.unit_price),format!("الإجمالي: {:.2} ج.م",s.total),"--------------------------------".into(),"شكراً لزيارتكم".into()];for text in rows{let t=wide(&text);let mut rect=RECT{left:margin,top:y,right,bottom:y+line};if DrawTextW(dc,PCWSTR(t.as_ptr()),(t.len()-1)as i32,&mut rect,DT_RIGHT|DT_RTLREADING|DT_SINGLELINE)==0{let e=last_error("تعذر رسم الإيصال العربي");let _=EndPage(dc);let _=EndDoc(dc);let _=SelectObject(dc,old);let _=DeleteObject(font);let _=DeleteDC(dc);return Err(e)}y+=line}let job=EndDoc(dc);let _=SelectObject(dc,old);let _=DeleteObject(font);let _=DeleteDC(dc);if job<=0{return Err(last_error("تعذر إرسال المهمة إلى Windows Spooler"))}Ok(format!("أرسل Windows Spooler المهمة #{job}. قبول المهمة لا يؤكد خروج الورقة."))}}
fn queue_path(app:&tauri::AppHandle)->Result<std::path::PathBuf,String>{Ok(app.path().app_config_dir().map_err(|e|e.to_string())?.join("printer-queue.txt"))}
#[tauri::command] fn save_queue(app:tauri::AppHandle,name:String)->Result<(),String>{if !list_printers()?.iter().any(|p|p.name==name){return Err("الطابعة غير موجودة في قائمة Windows".into())}let p=queue_path(&app)?;std::fs::create_dir_all(p.parent().unwrap()).map_err(|e|e.to_string())?;std::fs::write(p,name).map_err(|e|e.to_string())}
fn saved_queue(app:&tauri::AppHandle)->Result<String,String>{std::fs::read_to_string(queue_path(app)?).map(|s|s.trim().to_string()).map_err(|_|"احفظ Windows Printer Queue أولاً".into())}
#[tauri::command] fn print_receipt(app:tauri::AppHandle,sale:Sale,copies:u8,width:u16)->Result<Vec<String>,String>{if !(1..=3).contains(&copies)||![58,80].contains(&width){return Err("عدد النسخ أو مقاس الورق غير صالح".into())}let q=saved_queue(&app)?;if !list_printers()?.iter().any(|p|p.name==q){return Err(format!("الطابعة المحفوظة غير موجودة في Windows: {q}"))}let mut jobs=vec![];for _ in 0..copies{jobs.push(print_gdi(&q,&sale,width)?)}Ok(jobs)}
#[tauri::command] fn test_print(app:tauri::AppHandle,width:u16)->Result<String,String>{let q=saved_queue(&app)?;if ![58,80].contains(&width)||!list_printers()?.iter().any(|p|p.name==q){return Err("تحقق من مقاس الورق والطابعة المحفوظة".into())}print_gdi(&q,&Sale{id:0,product_name:"اختبار الطابعة".into(),quantity:1.0,unit_price:1.0,total:1.0,created_at:Local::now().to_rfc3339()},width)}
#[cfg_attr(mobile,tauri::mobile_entry_point)] pub fn run(){tauri::Builder::default().invoke_handler(tauri::generate_handler![list_printers,print_receipt,save_queue,test_print]).run(tauri::generate_context!()).expect("تعذر تشغيل مخبز أولاد عثمان")}
